#!/usr/bin/env python3
"""Builds static site into site/ from data/hosts.json. Run after updating prices."""
import json,pathlib,html
R=pathlib.Path(__file__).resolve().parent.parent;S=R/"site";D=json.load(open(R/"data/hosts.json"))
BASE="https://selfhostcalc.com"
H={h["id"]:h for h in D["hosts"]};U=D["updated"];N={p["name"]:p for p in D["n8n_cloud"]["plans"]}
(S/"assets/data.js").write_text("window.SC="+json.dumps(D,separators=(",",":"))+";")
NAV=[("index.html","Prices"),("calculator.html","Calculator"),("compare/cheapest-vps-for-n8n.html","Cheapest VPS"),("compare/n8n-cloud-vs-self-hosted.html","Cloud vs self-host"),("about.html","About")]
def page(path,title,desc,body,schema=None,js=False):
    up="../"*path.count("/")
    nav="".join(f'<a href="{up}{h}"{" class=on" if h==path else ""}>{t}</a>' for h,t in NAV)
    sc=schema or {"@context":"https://schema.org","@type":"WebPage","name":title,"description":desc,"dateModified":U}
    out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc)}"><link rel="canonical" href="{BASE}/{path.replace("index.html","")}">
<meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:type" content="website">
<link rel="stylesheet" href="{up}assets/style.css"><script type="application/ld+json">{json.dumps(sc)}</script></head><body>
<header><div class="wrap"><a class="logo" href="{up}index.html">Stack<b>Cost</b></a><nav>{nav}</nav></div></header><main class="wrap">{body}</main>
<footer><div class="wrap">Prices checked {U} from public pages; renewal prices matter more than intro deals. * Links marked “View deal” may become affiliate links — <a href="{up}affiliate-disclosure.html">disclosure</a>. · <a href="{up}about.html">About</a> · <a href="{up}newsletter.html">Newsletter</a></div></footer>
{f'<script src="{up}assets/data.js"></script><script src="{up}assets/app.js" defer></script>' if js else ''}</body></html>'''
    f=S/path;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(out);return path
pages=[]
NEWS='''<div class="card" style="margin-top:18px"><b>Get a weekly price-change email</b><p class="small" style="margin:4px 0 8px">Renewal hikes and new deals, once a week. No spam.</p><form id="newsletter" class="news" action="#TODO-newsletter-provider"><input type="email" required placeholder="you@example.com" aria-label="Email"><button class="btn">Subscribe</button></form><div id="nlmsg" class="small"></div></div>'''
# home
pages.append(page("index.html","n8n Hosting Prices Compared (Renewal Prices, "+U[:4]+") | StackCost","Real self-hosting costs for n8n on Hostinger, Contabo, Hetzner, OVHcloud, DigitalOcean, Vultr, Linode and more — renewal prices first, sourced and dated.",f'''
<h1>What self-hosting n8n really costs</h1><p class="lead">{sum(len(h["plans"]) for h in D["hosts"])} plans from {len(D["hosts"])} providers. Sorted by <b>renewal price</b> — the one you pay after the intro deal. Every price links to its source. <a href="calculator.html">Cloud vs VPS calculator →</a></p>
<div class="controls"><input id="q" placeholder="Search host or plan" aria-label="Search"><select id="ram" aria-label="Minimum RAM"><option value="">Any RAM</option><option value="2">≥ 2 GB</option><option value="4">≥ 4 GB</option><option value="8">≥ 8 GB</option></select><select id="ty" aria-label="Type"><option value="">All types</option><option value="vps">VPS</option><option value="paas">PaaS</option><option value="managed">Managed n8n</option></select><label class="chk"><input type="checkbox" id="oc"> 1-click n8n only</label><span id="count" class="small" style="align-self:center"></span></div>
<table class="cards lim"><thead><tr><th data-k="host">Host / plan</th><th data-k="ram">Specs</th><th data-k="renew">Renewal /mo</th><th>Term · install · source</th></tr></thead><tbody id="tbody"></tbody></table><button id="more" class="btn" type="button"></button>
<noscript><p>Enable JavaScript for the interactive table, or read the raw data at <a href="data/hosts.json">hosts.json</a>.</p></noscript>
<p class="small">“Unverified” = we could not confirm it on the provider’s public page, so we show nothing rather than guess. Taxes may apply. Hetzner prices are EUR excl. VAT.</p>{NEWS}''',js=True))
# calculator
pages.append(page("calculator.html","n8n Cloud vs Self-Hosted Calculator | StackCost","Enter your workflows and how often they run to see monthly executions, the cheapest n8n Cloud tier, the cheapest suitable VPS, and yearly savings.",'''
<h1>n8n Cloud vs self-hosting calculator</h1><p class="lead">Add your workflows → see executions/month, the n8n Cloud tier you’d need, and the cheapest VPS that fits.</p>
<form id="calc" class="card" onsubmit="return false"><div id="wfs"></div><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><button type="button" id="add" class="btn s">+ Add workflow</button><label class="small">n8n billing <select id="bill"><option value="monthly">monthly</option><option value="annual">annual</option></select></label></div></form>
<div class="kpi" style="margin-top:12px"><div><span>Executions / month</span><b id="ex">–</b></div><div><span>Cheapest n8n Cloud</span><b id="cloud">–</b><span id="cloudn"></span></div><div><span>Cheapest VPS (≥<i id="needram"></i> GB)</span><b id="vps">–</b><span id="vpsn"></span></div></div>
<p class="card" id="save" style="margin-top:12px"></p>
<details><summary>How this is calculated</summary><p class="small">Executions = workflows × runs per month (30-day month). n8n Cloud counts one execution per full workflow run regardless of steps. VPS RAM guide: 2 GB up to ~20k executions/mo, 4 GB up to ~200k, 8 GB beyond — a rule of thumb, not a benchmark. VPS price uses the <b>renewal</b> price of verified USD plans (VPS/managed, PaaS excluded because it is usage-billed). Self-hosted n8n Community Edition has no execution limit.</p></details>''',js=True))
# comparisons
def plans(id): return H[id]["plans"]
hs,co=H["hostinger"],H["contabo"]
def row(h,p): return f"<tr><td>{h['name']} {p['name']}</td><td>{p['vcpu'] or '?'} vCPU / {p['ram_gb'] or '?'} GB / {p['storage_gb'] or '?'} GB</td><td>{'$%.2f'%p['intro_price_mo'] if p['intro_price_mo'] else '—'}</td><td><b>{'$%.2f'%p['renewal_price_mo'] if p['renewal_price_mo'] else 'unverified'}</b></td></tr>"
TH="<table><thead><tr><th>Plan</th><th>Specs</th><th>Intro</th><th>Renewal</th></tr></thead><tbody>"
def faq(qs): return {"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in qs]}
C=[]
q=[("Is Hostinger or Contabo cheaper for n8n?",f"On renewal, Contabo's entry n8n VPS lists at ${co['plans'][0]['renewal_price_mo']:.2f}/mo for 4 vCPU/8 GB vs Hostinger KVM 1 at ${hs['plans'][0]['renewal_price_mo']:.2f}/mo for 1 vCPU/4 GB (checked {U}). Both require a 24-month term for the intro price.")]
C.append(("compare/hostinger-vs-contabo-n8n.html","Hostinger vs Contabo for n8n ("+U[:4]+" prices) | StackCost","Hostinger vs Contabo for self-hosting n8n: intro and renewal prices, specs, terms and one-click installs side by side.",f'''<h1>Hostinger vs Contabo for n8n</h1><p class="lead">Both offer a one-click n8n install and 24-month intro deals. The difference shows up at renewal and in specs.</p>
<div style="overflow-x:auto">{TH}{''.join(row(hs,p) for p in plans("hostinger")[:2])}{''.join(row(co,p) for p in plans("contabo")[:2])}</tbody></table></div>
<h2>Verdict</h2><p>{q[0][1]} Contabo gives more cores and RAM per dollar; Hostinger has NVMe storage and a more polished panel. Note: Contabo's “renewal” here is the struck-through regular price on its page — not explicitly labelled as renewal.</p><p><a class="btn s" href="{hs['affiliate']}" rel="sponsored nofollow">Hostinger*</a> <a class="btn s" href="{co['affiliate']}" rel="sponsored nofollow">Contabo*</a></p>''',faq(q)))
usd=sorted([(h,p) for h in D["hosts"] for p in h["plans"] if p["verified"] and p["currency"]=="USD" and p["renewal_price_mo"] and p["ram_gb"] and p["ram_gb"]>=2 and h["type"]=="vps"],key=lambda x:x[1]["renewal_price_mo"])
c=usd[0];q=[("What is the cheapest VPS for n8n?",f"By renewal price, {c[0]['name']} {c[1]['name']} at ${c[1]['renewal_price_mo']:.2f}/mo ({c[1]['ram_gb']} GB RAM), checked {U}.")]
C.append(("compare/cheapest-vps-for-n8n.html","Cheapest VPS for n8n — by Renewal Price | StackCost","The cheapest VPS plans with at least 2 GB RAM for running n8n, ranked by what you pay after the intro discount.",f'''<h1>Cheapest VPS for n8n</h1><p class="lead">Ranked by renewal price, verified USD plans with ≥ 2 GB RAM. Hetzner (EUR, from €5.99 excl. VAT) and OVHcloud (renewal unverified) are listed on the <a href="../index.html">main table</a>.</p>
<div style="overflow-x:auto">{TH}{''.join(row(h,p) for h,p in usd[:8])}</tbody></table></div><p>{q[0][1]}</p>''',faq(q)))
q=[("Can n8n run on 2 GB RAM?","Yes for light use: n8n itself idles at a few hundred MB. With SQLite and a handful of workflows 2 GB is workable; add Postgres, large binary data or many concurrent executions and 4 GB is safer. Add swap as a buffer.")]
two=[(h,p) for h,p in usd if p["ram_gb"]==2]
C.append(("compare/can-n8n-run-on-2gb-ram.html","Can n8n Run on 2 GB RAM? | StackCost","Whether a 2 GB VPS is enough for self-hosted n8n, what breaks first, and which 2 GB plans cost least.",f'''<h1>Can n8n run on 2 GB RAM?</h1><div class="prose"><p><b>Short answer: yes, for small setups.</b> {q[0][1][4:]}</p><ul><li>Fine: personal automations, webhooks, a few scheduled jobs, SQLite.</li><li>Tight: Postgres + n8n + reverse proxy on one box, AI agent workflows with big payloads.</li><li>Upgrade when: you see OOM kills or executions above ~20k/month.</li></ul></div>
<h2>2 GB plans by renewal price</h2><div style="overflow-x:auto">{TH}{''.join(row(h,p) for h,p in two)}</tbody></table></div><p class="small">Note: several providers (Hostinger, Contabo, OVHcloud) start at 4 GB+ for similar money — often the better buy.</p>''',faq(q)))
st,pr=N["Starter"],N["Pro"]
q=[("Is n8n Cloud or self-hosting cheaper?",f"n8n Cloud Starter is ${st['monthly']}/mo (${st['annual_mo']}/mo annual) for {st['executions']:,} executions; Pro is ${pr['monthly']}/mo for {pr['executions']:,}. A {c[0]['name']} VPS renews at ${c[1]['renewal_price_mo']:.2f}/mo with unlimited executions — about ${(st['monthly']-c[1]['renewal_price_mo'])*12:.0f}/yr cheaper than Starter, before your own time.")]
C.append(("compare/n8n-cloud-vs-self-hosted.html","n8n Cloud vs Self-Hosted: Real Cost ("+U[:4]+") | StackCost","n8n Cloud plan prices and execution limits vs the cost of a VPS for self-hosted n8n, with break-even math.",f'''<h1>n8n Cloud vs self-hosted cost</h1><div style="overflow-x:auto"><table><thead><tr><th>n8n plan</th><th>Monthly</th><th>Annual (per mo)</th><th>Executions/mo</th></tr></thead><tbody>{''.join(f"<tr><td>{p['name']} <span class=small>({p['hosting']})</span></td><td>{'$'+format(p['monthly'],',') if p['monthly'] else 'Contact'}</td><td>{'$'+format(p['annual_mo'],',') if p['annual_mo'] else '—'}</td><td>{format(p['executions'],',') if p['executions'] else 'Custom'}</td></tr>" for p in D['n8n_cloud']['plans'])}</tbody></table></div>
<p>{q[0][1]}</p><p><b>Choose Cloud</b> if you don’t want to patch servers or handle backups. <b>Self-host</b> if you run many executions, need data control, or want community nodes. <a href="../calculator.html">Run your own numbers →</a></p><p class="small">Source: <a href="{D['n8n_cloud']['url']}" rel="nofollow">n8n.io/pricing</a>, checked {U}.</p>''',faq(q)))
q=[("Is Hetzner or DigitalOcean better for n8n?","Hetzner is far cheaper (from €5.99/mo excl. VAT for 2 vCPU/4 GB) but EU/US/SG only and n8n isn't in its one-click list; DigitalOcean's 4 GB Basic droplet is $24/mo with a larger marketplace and more regions.")]
C.append(("compare/hetzner-vs-digitalocean-n8n.html","Hetzner vs DigitalOcean for n8n | StackCost","Hetzner Cloud vs DigitalOcean Droplets for self-hosted n8n: price per GB of RAM, billing and setup.",f'''<h1>Hetzner vs DigitalOcean for n8n</h1><p>{q[0][1]}</p><div style="overflow-x:auto">{TH}{''.join(row(H['digitalocean'],p) for p in plans('digitalocean'))}<tr><td>Hetzner Cost-Optimized (from)</td><td>2 vCPU / 4 GB / 40 GB</td><td>€5.99</td><td><b>€5.99</b> excl. VAT</td></tr></tbody></table></div><p class="small">Hetzner per-plan prices beyond “starting from” were not captured and are left unverified. Both bill hourly with no term.</p>''',faq(q)))
for a in C: pages.append(page(*a))
pages.append(page("newsletter.html","StackCost Newsletter | Weekly n8n Hosting Price Changes","Get a weekly email when n8n hosting prices or renewal terms change.",'<h1>Newsletter</h1><p class="lead">One short email a week: price changes, renewal hikes and new n8n hosting deals.</p>'+NEWS,js=True))
pages.append(page("affiliate-disclosure.html","Affiliate Disclosure | StackCost","How StackCost may earn money and how that does not affect rankings.",'<div class="prose"><h1>Affiliate disclosure</h1><p>Some “View deal” links on StackCost may become affiliate links: if you buy through them we may earn a commission at no extra cost to you. <b>At the moment no affiliate programs are active</b> — those links are placeholders.</p><p>Rankings are sorted by price data only (renewal price by default). Commissions never change the order, and we never show a price we could not verify on the provider’s public page.</p></div>'))
pages.append(page("about.html","About StackCost","StackCost tracks what it really costs to self-host n8n and AI automation tools, using sourced and dated prices.",f'<div class="prose"><h1>About StackCost</h1><p>StackCost is built by Hayden Young to answer one question honestly: <b>what does self-hosting n8n actually cost after the intro deal ends?</b></p><h2>Method</h2><ul><li>Prices come only from providers’ public pages or public APIs, with the source URL and date checked.</li><li>Renewal price is shown first. If we can’t verify a number, we leave it blank and mark it unverified.</li><li>A script re-checks every source weekly and flags changes for review.</li></ul><p>Last full check: {U}. Raw data: <a href="data/hosts.json">hosts.json</a>.</p></div>'))
(S/"data").mkdir(exist_ok=True);(S/"data/hosts.json").write_text(json.dumps(D,indent=1))
(S/"sitemap.xml").write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+"".join(f"<url><loc>{BASE}/{p.replace('index.html','')}</loc><lastmod>{U}</lastmod></url>" for p in pages)+"</urlset>")
(S/"robots.txt").write_text(f"User-agent: *\nAllow: /\nSitemap: {BASE}/sitemap.xml\n")
print(len(pages),"pages")
